
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_3_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_3", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.859895072903603e+00, -4.764498658218209e+00, -4.630775255123375e+00, -4.445411281105624e+00, -4.192505185595546e+00, -3.855001317811042e+00, -3.417891597227746e+00, -2.872720233323840e+00, -2.220872281476560e+00, -1.495707014728037e+00, -8.801348619126489e-01, -6.330350588476633e-01, -6.218960497287134e-01, -5.268440081466383e-01, -3.604536862793213e-01, -1.973297768855054e-01, -8.600975567435565e-02, -2.844082676594876e-02, -6.110823806706831e-03, -6.881608318598047e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


